const writeActionTests = require('./writeActionTests');
const Cases = require('../../../tools/cases');
const {
  parseCamelCaseToArray,
  cleanFile,
  fixInlineImports,
  transforms,
} = require('../../../tools/utils');

module.exports = ({ buffer, arrayOfDomains }) =>
  transforms(buffer, [
    cleanFile,
    fixInlineImports,
    ...arrayOfDomains.map(({ domainName, initialState, actions }) => b => {
      const cases = new Cases(parseCamelCaseToArray(domainName));
      const allDomainCases = cases.all();

      const arrayOfActions = Object.keys(actions).map(key => ({
        ...actions[key],
        name: key,
        cases: new Cases(parseCamelCaseToArray(key)).all(),
      }));

      return writeActionTests({
        buffer: b,
        domainCases: allDomainCases,
        arrayOfActions,
        initialState,
      });
    }),
  ]);

const {
  transforms,
  prettify,
  concat,
  ensureImport,
} = require('../../../tools/utils');

module.exports = ({ buffer, arrayOfActions }) =>
  transforms(buffer, [
    ...arrayOfActions.map(action => buf =>
      transforms(buf, [
        ensureImport(action.name, '../actions', { destructure: true }),
        ensureImport(action.cases.constant, '../constants', {
          destructure: true,
        }),
      ]),
    ),
    ...arrayOfActions.map(action => buf =>
      concat([
        buf,
        `// @suit-start`,
        `describe('${action.cases.camel}', () => {`,
        `  it('should have the correct type', () => {`,
        `    expect(${action.cases.camel}().type).toEqual(${
          action.cases.constant
        });`,
        `  });`,
        action.set &&
        Object.values(action.set).filter(val => `${val}`.includes('payload'))
          .length > 0
          ? concat([
              `  it('should return the correct payload', () => {`,
              `    expect(${
                action.cases.camel
              }('dummyPayload').payload).toEqual('dummyPayload');`,
              `  });`,
            ])
          : null,
        `});`,
        `// @suit-end`,
        ``,
      ]),
    ),
    prettify,
  ]);

