const writeActions = require('./writeActions');
const Cases = require('../../../tools/cases');
const {
  transforms,
  cleanFile,
  fixInlineImports,
  parseCamelCaseToArray,
} = require('../../../tools/utils');

module.exports = ({ arrayOfDomains, buffer }) => {
  const newActionsBuffer = transforms(buffer, [
    cleanFile,
    fixInlineImports,
    ...arrayOfDomains.map(({ domainName, actions }) => b => {
      const cases = new Cases(parseCamelCaseToArray(domainName));
      const allDomainCases = cases.all();

      return writeActions({
        buffer: b,
        cases: allDomainCases,
        actions,
      });
    }),
  ]);
  return { buffer: newActionsBuffer };
};

const { concat, transforms, prettify } = require('../../../tools/utils');
const writeOneAction = require('./writeOneAction');

module.exports = ({ buffer, cases, actions }) =>
  transforms(buffer, [
    /** Adds the domain */
    b => concat([b, `// @suit-start`, ``, `/** ${cases.display} actions */`]),
    /** Adds each action */
    ...Object.keys(actions)
      .map(key => ({ name: key, ...actions[key] }))
      .reverse()
      .map(writeOneAction(cases)),
    prettify,
  ]);

const { concat, printObject } = require('../../../tools/utils');

module.exports = ({ action }) => {
  if (action.customFunction) {
    return concat([
      `      return ${action.name}CustomFunction(state${
        action.payload ? ', payload' : ''
      });`,
    ]);
  }

  if (!action.set) {
    return concat([`      return state;`]);
  }

  return (
    concat([
      `      return state`,
      ...Object.entries(action.set)
        .map(entry => ({
          key: entry[0],
          value: entry[1],
        }))
        .map(({ key, value }) => {
          if (typeof value === 'string' && !value.includes('payload')) {
            /* eslint-disable no-param-reassign */
            value = `'${value}'`;
          } else if (typeof value === 'object' && value !== null) {
            value = printObject(value, '          ');
          }
          return `        .set('${key}', ${value})`;
        }),
    ]) + ';'
  );
};

const Parser = require('../../../tools/parser');
const Cases = require('../../../tools/cases');
const writeActionsInReducer = require('./writeActionsInReducer');
const { concat, parseCamelCaseToArray } = require('../../../tools/utils');

module.exports = ({ camel, actions }) => buffer => {
  const p = new Parser(buffer);
  p.resetTicker();
  p.toNext(`export const ${camel}Reducer =`);
  const searchTerm = `switch (type) {`;
  const startIndex = p.toNext(searchTerm).index + searchTerm.length;
  let content = '';
  Object.keys(actions)
    .map(key => ({ ...actions[key], name: key }))
    .forEach(action => {
      const c = new Cases(parseCamelCaseToArray(action.name));
      const cases = c.all();

      const operations = writeActionsInReducer({
        action,
      });

      content += concat([
        action.describe ? `    // ${action.describe}` : null,
        `    case ${cases.constant}:`,
        operations,
        ``,
      ]);
    });
  return (
    concat([
      buffer.slice(0, startIndex),
      `    // @suit-start`,
      content + `    // @suit-end`,
    ]) +
    `    ` +
    buffer.slice(startIndex)
  );
};

const Cases = require('../../../tools/cases');
const {
  concat,
  parseCamelCaseToArray,
  ensureImport,
} = require('../../../tools/utils');

/**
 * Writes one action to the file
 * @param {object} domainCases
 */
module.exports = domainCases => (
  { name, set, payload: payloadAttribute, describe },
  i,
) => buffer => {
  const c = new Cases(parseCamelCaseToArray(name));
  const actionCases = c.all();
  /** Ensures the imports of the constants */
  const newBuffer = ensureImport(actionCases.constant, './constants', {
    destructure: true,
  })(buffer);

  const searchTerm = `/** ${domainCases.display} actions */`;
  const index = newBuffer.indexOf(searchTerm) + searchTerm.length;

  let content = '';
  const hasPayload =
    (set &&
      Object.values(set).filter(value => `${value}`.includes('payload'))
        .length > 0) ||
    payloadAttribute;
  content += concat([
    ``,
    describe ? `// ${describe}` : null,
    `export const ${actionCases.camel} = (${
      hasPayload ? 'payload' : ''
    }) => ({`,
    `  type: ${actionCases.constant},`,
    hasPayload ? `  payload,` : null,
    `});`,
  ]);
  if (i === 0) {
    content += '\n\n// @suit-end';
  }

  return concat([newBuffer.slice(0, index), content, newBuffer.slice(index)]);
};

