const {
  transforms,
  prettify,
  concat,
  ensureImport,
  parseCamelCaseToArray,
  getDomainNameFromFolder,
  printObject,
  unCapitalize,
} = require('../../../tools/utils');
const Cases = require('../../../tools/cases');

module.exports = ({ buffer, cases, initialState, folder }) =>
  transforms(buffer, [
    ensureImport('fromJS', 'immutable', { destructure: true }),
    /** Creates a mocked-up version of the state for testing */
    b => {
      const toInsert = concat([
        `const mockedState = fromJS({`,
        `  ${unCapitalize(getDomainNameFromFolder(folder))}: {`,
      ]);
      if (b.indexOf(toInsert) === -1) {
        return concat([
          b,
          `// @suit-start`,
          toInsert,
          `  },`,
          `});`,
          `// @suit-end`,
        ]);
      }
      return b;
    },
    /** Fills in that mocked-up state */
    b => {
      const searchTerm = concat([
        `const mockedState = fromJS({`,
        `  ${unCapitalize(getDomainNameFromFolder(folder))}: {`,
      ]);
      const index = b.indexOf(searchTerm) + searchTerm.length;
      return concat([
        b.slice(0, index),
        `    ${cases.camel}: ${printObject(initialState, '    ')},` +
          b.slice(index),
      ]);
    },
    ensureImport(`makeSelect${cases.pascal}`, '../selectors', {
      destructure: true,
    }),
    b =>
      concat([
        b,
        `// @suit-start`,
        `describe('makeSelect${cases.pascal}', () => {`,
        `  it('should return the correct value', () => {`,
        `    const selector = makeSelect${cases.pascal}();`,
        `    expect(selector(mockedState))`,
        `      .toEqual(fromJS(mockedState.get('${unCapitalize(
          getDomainNameFromFolder(folder),
        )}').get('${cases.camel}')));`,
        `  });`,
        `});`,
        `// @suit-end`,
      ]),
    ...Object.keys(initialState)
      .map(key => new Cases(parseCamelCaseToArray(key)).all())
      .map(fieldCases =>
        ensureImport(
          `makeSelect${cases.pascal}${fieldCases.pascal}`,
          '../selectors',
          { destructure: true },
        ),
      ),
    ...Object.keys(initialState)
      .map(key => ({
        key,
        value:
          /* eslint-disable no-nested-ternary */
          typeof initialState[key] === 'string'
            ? `'${initialState[key]}'`
            : typeof initialState[key] === 'object' &&
              initialState[key] !== null
              ? `fromJS(${printObject(initialState[key], '      ')})`
              : initialState[key],
        cases: new Cases(parseCamelCaseToArray(key)).all(),
      }))
      .map(field => b =>
        concat([
          b,
          `// @suit-start`,
          `describe('makeSelect${cases.pascal}${field.cases.pascal}', () => {`,
          `  it('should return the correct value', () => {`,
          `    const selector = makeSelect${cases.pascal}${
            field.cases.pascal
          }();`,
          `    expect(selector(mockedState))`,
          `      .toEqual(${field.value});`,
          `  });`,
          `});`,
          `// @suit-end`,
          ``,
        ]),
      ),
    prettify,
  ]);

const {
  transforms,
  prettify,
  concat,
  printObject,
  ensureImport,
  parseCamelCaseToArray,
} = require('../../../tools/utils');
const Cases = require('../../../tools/cases');

module.exports = ({ buffer, cases, actions, initialState }) =>
  transforms(buffer, [
    ensureImport('fromJS', 'immutable', { destructure: true }),
    ensureImport(`${cases.camel}Reducer`, '../reducer', { destructure: true }),
    ...Object.keys(actions)
      .filter(action => !actions[action].customFunction)
      .map(actionName => buf => {
        const actionCases = new Cases(parseCamelCaseToArray(actionName)).all();
        return transforms(buf, [
          ensureImport(actionCases.camel, '../actions', {
            destructure: true,
          }),
        ]);
      }),
    b =>
      concat([
        b,
        `// @suit-start`,
        `describe('${cases.camel}Reducer', () => {`,
        `  it('returns the initial state', () => {`,
        `    expect(${cases.camel}Reducer(undefined, { type: '' }))`,
        `      .toEqual(fromJS(${printObject(initialState, '      ')}),`,
        `    );`,
        `  });`,
        /** Test each action in the reducer */
        ...Object.keys(actions)
          .map(key => ({ ...actions[key], name: key }))
          .map(action => {
            /** TODO: make this better */
            if (!action.set) return ``;
            const arrayOfSets = Object.keys(action.set)
              .map(key => ({
                key,
                value: action.set[key],
                hasPayload: `${action.set[key]}`.includes('payload'),
              }))
              .map(set => ({
                ...set,
                value:
                  typeof set.value === 'string' && !set.hasPayload
                    ? `'${set.value}'`
                    : typeof set.value === 'object' && set.value !== null
                      ? printObject(set.value, '        ')
                      : set.value,
              }));
            const payloadValues = arrayOfSets
              .filter(({ hasPayload }) => hasPayload)
              .map(({ value }) => value);
            // Checks if payload should be rendered as an object
            const payloadIsObject =
              payloadValues.length > 1 ||
              payloadValues.filter(val => val.includes('.')).length;
            return concat([
              `  describe('${action.name}', () => {`,
              `    it('alters the state as expected', () => {`,
              // if only passes one payload, only test one payload
              payloadValues.length === 1 && !payloadIsObject
                ? `      const payload = 'dummyPayload';`
                : null,
              // If multiple payloads, define payload as an object and define properties
              payloadIsObject ? `      const payload = {};` : null,
              payloadIsObject
                ? concat([
                    ...payloadValues.map(
                      value => `      ${value} = 'dummyPayload';`,
                    ),
                  ])
                : null,
              `      const newState = ${cases.camel}Reducer(`,
              `        undefined,`,
              // If it has a payload, pass it to the action creator
              `        ${action.name}(${
                payloadValues.length > 0 ? 'payload' : ''
              }),`,
              `      );`,
              ...arrayOfSets.map(({ key, value }) =>
                concat([
                  `      expect(newState.get('${key}')).toEqual(${value});`,
                ]),
              ),
              `    });`,
              `  });`,
            ]);
          }),
        `});`,
        `// @suit-end`,
        ``,
      ]),
    prettify,
  ]);

